public static int countOilDeposits(char[][] grid) {
    int n = grid.length;
    int m = grid[0].length;
    int count = 0;
    boolean[][] visited = new boolean[n][m];

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                dfs(grid, visited, i, j);
                count++;
            }
        }
    }

    return count;
}

private static void dfs(char[][] grid, boolean[][] visited, int i, int j) {
    visited[i][j] = true;
    int n = grid.length;
    int m = grid[0].length;

    if (i > 0 && grid[i - 1][j] == '@' && !visited[i - 1][j]) {
        dfs(grid, visited, i - 1, j);
    }
    if (i < n - 1 && grid[i + 1][j] == '@' && !visited[i + 1][j]) {
        dfs(grid, visited, i + 1, j);
    }
    if (j > 0 && grid[i][j - 1] == '@' && !visited[i][j - 1]) {
        dfs(grid, visited, i, j - 1);
    }
    if (j < m - 1 && grid[i][j + 1] == '@' && !visited[i][j + 1]) {
        dfs(grid, visited, i, j + 1);
    }
}
