public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a boolean array to keep track of visited n-tersections
    boolean[] visited = new boolean[n];

    // Initialize a Queue to keep track of the n-tersections to be visited
    Queue<int[]> queue = new LinkedList<>();

    // Add the starting n-tersection to the queue
    queue.add(start);

    // Mark the starting n-tersection as visited
    visited[start[0]] = true;

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Dequeue an n-tersection
        int[] current = queue.poll();

        // Check if the current n-tersection is the ending n-tersection
        if (current[0] == end[0] && current[1] == end[1]) {
            // If it is, return "can be travelled"
            return "can be travelled";
        }

        // Get the adjacent n-tersections of the current n-tersection
        int[][] adjacent = getAdjacentNtersections(current, n, paths);

        // Loop through the adjacent n-tersections
        for (int[] adj : adjacent) {
            // Check if the current n-tersection has not been visited
            if (!visited[adj[0]]) {
                // If it has not, mark it as visited and add it to the queue
                visited[adj[0]] = true;
                queue.add(adj);
            }
        }
    }

    // If the queue is empty, return "cannot be travelled"
    return "cannot be travelled";
}

// Helper method to get the adjacent n-tersections of a given n-tersection
private static int[][] getAdjacentNtersections(int[] ntersection, int n, int[][] paths) {
    // Create a list to store the adjacent n-tersections
    List<int[]> adjacent = new ArrayList<>();

    // Loop through the paths
    for (int[] path : paths) {
        // Check if the current path is adjacent to the given n-tersection
        if (path[0] == ntersection[0] || path[1] == ntersection[0]) {
            // If it is, add the adjacent n-tersection to the list
            adjacent.add(new int[] {path[0] == ntersection[0] ? path[1] : path[0], ntersection[1]});
        }
    }

    // Return the list of adjacent n-tersections
    return adjacent.toArray(new int[adjacent.size()][]);
}
