public boolean canArrange(int[] arr, int k) {
    Arrays.sort(arr);
    int n = arr.length;
    int[] prefixSums = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        prefixSums[i] = prefixSums[i - 1] + arr[i - 1];
    }
    for (int i = 1; i <= n / 2; i++) {
        int sum = prefixSums[n] - prefixSums[i - 1] - prefixSums[n - i + 1];
        if (sum % k == 0) {
            return true;
        }
    }
    return false;
}
