private static int findMaxLength(int[][] mat, int i, int j) {
    int length = 1;
    int rows = mat.length;
    int cols = mat[0].length;
    int[][] visited = new int[rows][cols];
    Queue<int[]> queue = new LinkedList<>();
    queue.add(new int[]{i, j});
    visited[i][j] = 1;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int x = current[0];
        int y = current[1];

        if (x - 1 >= 0 && mat[x - 1][y] == 1 && visited[x - 1][y] == 0) {
            queue.add(new int[]{x - 1, y});
            visited[x - 1][y] = 1;
            length++;
        }
        if (x + 1 < rows && mat[x + 1][y] == 1 && visited[x + 1][y] == 0) {
            queue.add(new int[]{x + 1, y});
            visited[x + 1][y] = 1;
            length++;
        }
        if (y - 1 >= 0 && mat[x][y - 1] == 1 && visited[x][y - 1] == 0) {
            queue.add(new int[]{x, y - 1});
            visited[x][y - 1] = 1;
            length++;
        }
        if (y + 1 < cols && mat[x][y + 1] == 1 && visited[x][y + 1] == 0) {
            queue.add(new int[]{x, y + 1});
            visited[x][y + 1] = 1;
            length++;
        }
    }

